// Snoop: for each watched target, detect new upload and auto-clip it.
// Talks to the native pipeline-api on localhost:8000.
const BASE = 'http://localhost:8000';
const req = (opts) => this.helpers.httpRequest({ json: true, ...opts });

const targetsResp = await req({ url: `${BASE}/snoop/targets` });
const targets = (targetsResp && targetsResp.targets) || [];
const out = [];

for (const t of targets) {
  let latest;
  try {
    const up = await req({ url: `${BASE}/youtube/channel/${encodeURIComponent(t.channel_id)}/uploads?max_results=1` });
    latest = (up.items || [])[0];
  } catch (e) {
    out.push({ channel_id: t.channel_id, error: `uploads: ${e.message}` });
    continue;
  }
  if (!latest) continue;
  const videoId = latest.video_id || latest.id;
  if (!videoId || videoId === t.last_seen_video_id) continue; // nothing new

  const youtubeUrl = `https://www.youtube.com/watch?v=${videoId}`;
  let clips = [];
  let clipSuccess = false;
  try {
    const clipResp = await req({ method: 'POST', url: `${BASE}/clips/find-claude`, body: { youtube_url: youtubeUrl } });
    clips = (clipResp && clipResp.clips) || [];
    clipSuccess = true;
  } catch (e) {
    out.push({ channel_id: t.channel_id, video_id: videoId, error: `clip: ${e.message}` });
    // B3: do NOT advance last_seen on clip failure; skip the results update
    continue;
  }
  try {
    await req({ method: 'POST', url: `${BASE}/snoop/results`, body: { channel_id: t.channel_id, video_id: videoId, video_title: latest.title || '', clips } });
  } catch (e) {
    out.push({ channel_id: t.channel_id, video_id: videoId, error: `store: ${e.message}` });
    continue;
  }
  out.push({ channel_id: t.channel_id, handle: t.handle, video_id: videoId, title: latest.title || '', clips: clips.length });
}

return out.length ? out.map((o) => ({ json: o })) : [{ json: { checked: targets.length, new: 0 } }];
